sealed class Parser
{
    readonly Dictionary<(int Rule, int Pos), Memo> memo = new();
    Memo Rule(int rule, int pos)
    {
        if (memo.TryGetValue((rule, pos), out var hit)) return hit; // success or failure
        var m = RuleImpl(rule, pos);         // ordinary recursive descent, may backtrack
        memo[(rule, pos)] = m;               // failures are memoized too
        return m;
    }
}
